const BASE_URL = "https://homologacao.focusnfe.com.br"; // produção: https://api.focusnfe.com.br
const TOKEN = process.env.FOCUS_TOKEN ?? "<<SEU_TOKEN>>";
const AUTH = "Basic " + Buffer.from(`${TOKEN}:`).toString("base64"); // senha vazia
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function chamar(metodo: string, caminho: string, corpo?: unknown, tentativas = 4): Promise<Response> {
  for (let i = 0; ; i++) {
    const resp = await fetch(BASE_URL + caminho, {
      method: metodo,
      headers: { Authorization: AUTH, "Content-Type": "application/json" },
      body: corpo === undefined ? undefined : JSON.stringify(corpo),
    });
    if (resp.status === 429 && i < tentativas - 1) {
      await sleep(Number(resp.headers.get("Rate-Limit-Reset") ?? resp.headers.get("Retry-After") ?? "60") * 1000);
      continue;
    }
    if (resp.status >= 500 && i < tentativas - 1) {
      await sleep(2 ** i * 1000);
      continue;
    }
    return resp;
  }
}

async function exigirOk(resp: Response, aceitos: number[]): Promise<void> {
  if (!aceitos.includes(resp.status)) {
    throw new Error(`Focus NFe HTTP ${resp.status}: ${await resp.text()}`);
  }
}

