async function buscarNovos(filtros: Record<string, string>, ultimaVersao = 0) {
  const docs: unknown[] = [];
  while (true) {
    const q = new URLSearchParams({ ...filtros, versao: String(ultimaVersao) });
    const resp = await chamar("GET", `/v2/nfes_recebidas?${q}`);
    await exigirOk(resp, [200]);
    const pagina = (await resp.json()) as unknown[];
    if (pagina.length === 0) break;
    docs.push(...pagina);
    const maxV = Number(resp.headers.get("X-Max-Version") ?? Math.max(...pagina.map((d: any) => Number(d.versao ?? 0))));
    if (!maxV || maxV <= ultimaVersao) break;
    ultimaVersao = maxV;
  }
  return { docs, ultimaVersao };
}

