async function listarTudo(filtros: Record<string, string>): Promise<unknown[]> {
  const itens: unknown[] = [];
  let offset = 0;
  while (true) {
    const q = new URLSearchParams({ ...filtros, offset: String(offset) });
    const resp = await chamar("GET", `/v2/ceps?${q}`);
    await exigirOk(resp, [200]);
    const pagina = (await resp.json()) as unknown[];
    if (pagina.length === 0) break;
    itens.push(...pagina);
    offset += pagina.length;
    const total = Number(resp.headers.get("X-Total-Count") ?? 0);
    if (total && offset >= total) break;
  }
  return itens;
}

